macro_rules! deps {
    () => {
        Adjust!();
    };
}

macro_rules! Adjustment {
    () => {
        deps!();
        # [doc = " Represents coercing a value to a different type of value."] # [doc = ""] # [doc = " We transform values by following a number of `Adjust` steps in order."] # [doc = " See the documentation on variants of `Adjust` for more details."] # [doc = ""] # [doc = " Here are some common scenarios:"] # [doc = ""] # [doc = " 1. The simplest cases are where a pointer is not adjusted fat vs thin."] # [doc = "    Here the pointer will be dereferenced N times (where a dereference can"] # [doc = "    happen to raw or borrowed pointers or any smart pointer which implements"] # [doc = "    Deref, including Box<_>). The types of dereferences is given by"] # [doc = "    `autoderefs`. It can then be auto-referenced zero or one times, indicated"] # [doc = "    by `autoref`, to either a raw or borrowed pointer. In these cases unsize is"] # [doc = "    `false`."] # [doc = ""] # [doc = " 2. A thin-to-fat coercion involves unsizing the underlying data. We start"] # [doc = "    with a thin pointer, deref a number of times, unsize the underlying data,"] # [doc = "    then autoref. The 'unsize' phase may change a fixed length array to a"] # [doc = "    dynamically sized one, a concrete object to a trait object, or statically"] # [doc = "    sized struct to a dynamically sized one. E.g., &[i32; 4] -> &[i32] is"] # [doc = "    represented by:"] # [doc = ""] # [doc = "    ```ignore"] # [doc = "    Deref(None) -> [i32; 4],"] # [doc = "    Borrow(AutoBorrow::Ref) -> &[i32; 4],"] # [doc = "    Unsize -> &[i32],"] # [doc = "    ```"] # [doc = ""] # [doc = "    Note that for a struct, the 'deep' unsizing of the struct is not recorded."] # [doc = "    E.g., `struct Foo<T> { it: T }` we can coerce &Foo<[i32; 4]> to &Foo<[i32]>"] # [doc = "    The autoderef and -ref are the same as in the above example, but the type"] # [doc = "    stored in `unsize` is `Foo<[i32]>`, we don't store any further detail about"] # [doc = "    the underlying conversions from `[i32; 4]` to `[i32]`."] # [doc = ""] # [doc = " 3. Coercing a `Box<T>` to `Box<dyn Trait>` is an interesting special case. In"] # [doc = "    that case, we have the pointer we need coming in, so there are no"] # [doc = "    autoderefs, and no autoref. Instead we just do the `Unsize` transformation."] # [doc = "    At some point, of course, `Box` should move out of the compiler, in which"] # [doc = "    case this is analogous to transforming a struct. E.g., Box<[i32; 4]> ->"] # [doc = "    Box<[i32]> is an `Adjust::Unsize` with the target `Box<[i32]>`."] # [derive (Clone , Debug , PartialEq , Eq , Hash , TypeVisitable , TypeFoldable)] pub struct Adjustment < 'db > { # [type_visitable (ignore)] # [type_foldable (identity)] pub kind : Adjust , pub target : Ty < 'db > , }
    };
}

Adjustment!()